#!/usr/bin/env bash
# Creates config/passwords.yaml with fresh random secrets for development and
# test, if it does not exist yet. The file is git-ignored; never commit it.
set -euo pipefail
cd "$(dirname "$0")/.."
f=config/passwords.yaml
if [ -f "$f" ]; then echo "$f exists; leaving it alone."; exit 0; fi
r() { head -c 48 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c "${1:-32}"; }
cat > "$f" <<YAML
# Generated by tool/gen_passwords.sh — local development only. Git-ignored.
development:
  database: '$(r)'
  redis: '$(r)'
  serviceSecret: '$(r)'
  emailSecretHashPepper: '$(r)'
  jwtHmacSha512PrivateKey: '$(r 64)'
  jwtRefreshTokenHashPepper: '$(r)'
test:
  database: '$(r)'
  redis: '$(r)'
  emailSecretHashPepper: '$(r)'
  jwtHmacSha512PrivateKey: '$(r 64)'
  jwtRefreshTokenHashPepper: '$(r)'
YAML
echo "Wrote $f"
